derivation_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Control regimen" AS source_value FROM clinical_trials
WHERE "Name of ICI" = 'Chemotherapy' AND "Cancer type" = 'Prostate' AND "Control arm" = 'Chemo'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_specific_regimens(source_value) AS "specific_regimens"
FROM base;
